from openpyxl import load_workbook

# Load the workbook and select the sheet
wb = load_workbook("input.xlsx")
sheet = wb["Sheet2"]

# Create a dictionary to store employee data
employee_data = {}

# Iterate through the rows and collect data
for row in sheet.iter_rows(min_row=2, max_row=92, values_only=True):
    date, emp_num, abs_name, atts_name, week = row
    if emp_num not in employee_data:
        employee_data[emp_num] = {}
    if week not in employee_data[emp_num]:
        employee_data[emp_num][week] = {"sick": False, "overtime": False}

    if abs_name == "Sick Day":
        employee_data[emp_num][week]["sick"] = True
    if atts_name == "Overtime":
        employee_data[emp_num][week]["overtime"] = True

# Prepare the result for the output range
result = []
for week in sorted(employee_data[133049].keys()):
    if employee_data[133049][week]["sick"] and employee_data[133049][week]["overtime"]:
        result.append("y")
    else:
        result.append("")

# Write the result to the output range
for i, value in enumerate(result):
    sheet[f"F{i + 2}"] = value

# Save the workbook as output.xlsx
wb.save("output.xlsx")
